  if [[ -f $directory/cupti.h ]]; then cupti_include=$directory; break; fi
done
for directory in "$CUDA_LIB" "${CUDA_ROOT:-/nonexistent}/extras/CUPTI/lib64" "${CUDA_ROOT:-/nonexistent}/targets/x86_64-linux/lib" /usr/lib/x86_64-linux-gnu; do
  if [[ -f $directory/libcupti.so ]]; then cupti_lib=$directory; break; fi
done
