struct Row { uint64_t start,end; std::string name; int kind; };
static std::vector<Row> *rows;
static std::mutex *lock;
static uint64_t origin;
static double host_origin;
static size_t dropped=0;
static bool failed=false;
static void check(CUptiResult status) {
  if(status"'!=CUPTI_SUCCESS) { const char *s=nullptr; cuptiGetResultString(status,&s); fprintf(stderr,"CUPTI: %s'"\\n\",s?s:\"unknown error\"); failed=true; }
}
static void CUPTIAPI request(uint8_t **buffer,size_t *size,size_t *maxRecords) {
  *size=8*1024*1024; *maxRecords=0;
  if(posix_memalign((void**)buffer,8,*size)"'!=0) { fprintf(stderr,"CUPTI buffer allocation failed'"\\n\"); abort(); }
}
static void CUPTIAPI complete(CUcontext context,uint32_t stream,uint8_t *buffer,size_t,size_t valid) {
  CUpti_Activity *record;
  while(true) {
    CUptiResult result=cuptiActivityGetNextRecord(buffer,valid,&record);
    if(result==CUPTI_ERROR_MAX_LIMIT_REACHED) break;
    if(result"'!=CUPTI_SUCCESS) {check(result);break;}
    Row row{};
