      row={m->start,m->end,"CUDA memcpy kind "+std::to_string((int)m->copyKind),1};
    } else if(record->kind==CUPTI_ACTIVITY_KIND_MEMSET) {
      auto *m=(CUpti_ActivityMemset*)record;
      row={m->start,m->end,"CUDA memset",1};
    } else if(record->kind==CUPTI_ACTIVITY_KIND_RUNTIME) {
      auto *a=(CUpti_ActivityAPI*)record;
      const char *name=nullptr;
      check(cuptiGetCallbackName(CUPTI_CB_DOMAIN_RUNTIME_API,a->cbid,&name));
      row={a->start,a->end,name?name:"CUDA runtime",2};
    } else continue;
