for index,line in enumerate(lines[1:]):
    a,b,kind,name=line.split('\\t',3)
    a=host_origin+(int(a)-origin)*1e-9-begin
    b=host_origin+(int(b)-origin)*1e-9-begin
    a=max(0,a); b=min(total,b); kind=int(kind)
    if b>a: activities.append((a,b,kind,name,index))
if not any(a[2]==0 for a in activities): raise RuntimeError('Missing measured compute activity')
# Sweep the actual activity endpoints. GPU activity owns overlap with host APIs;
# each critical-path interval contributes once, even with concurrent streams.
events=[]
for index,(a,b,kind,name,_) in enumerate(activities):
    events.extend([(a,1,index),(b,-1,index)])
events.sort()
active=set(); cursor=0.0; stages=[]; gpu_seen=False

def interval(a,b):
    global gpu_seen
    if b<=a: return
    gpu=[i for i in active if activities[i][2]<2]
    cpu=[i for i in active if activities[i][2]==2]
    if gpu:
        # Prefer the longest still-active operation when activities overlap.
        chosen=max(gpu,key=lambda i:activities[i][1])
        row=activities[chosen]; name=row[3]; kind='compute' if row[2]==0 else 'transfer'
        gpu_s=b-a; gpu_seen=True
    elif cpu:
        chosen=max(cpu,key=lambda i:activities[i][0]); row=activities[chosen]
        name=row[3]; kind='other'; gpu_s=None
    else:
        name='host result finalization' if gpu_seen else 'host setup and input generation'
        kind='other'; gpu_s=None
    if stages and stages[-1]['stage']==name and stages[-1]['kind']==kind:
        stages[-1]['wall_s']+=b-a
        if gpu_s is not None: stages[-1]['gpu_s']+=gpu_s
    else: stages.append({'stage':name,'kind':kind,'wall_s':b-a,'gpu_s':gpu_s})
for t,direction,index in events:
    interval(cursor,t); cursor=t
    if direction==1: active.add(index)
    else: active.discard(index)
interval(cursor,total)
# Remove synchronization API waits: they are process waits rather than timed
# program phases. Overlapping GPU work has already been attributed above.
stages=[s for s in stages if not (s['kind']=='other' and any(x in s['stage'] for x in ('Synchronize','EventQuery','StreamQuery')))]
# Do not report a nearly process-length interval as a profiling stage.
stages=[s for s in stages if abs(s['wall_s']-total)>.02*total]
(out/'stages.json').write_text(json.dumps(stages,allow_nan=False)+'\\n')
if len(stages)<3: raise RuntimeError('Trace contains fewer than three internal timed stages')
if min(1,sum(s['wall_s'] for s in stages)/total)<.9: raise RuntimeError('Internal timed stages cover less than 90% of measured run')
for s in stages:
    if not math.isfinite(s['wall_s']) or s['wall_s']<0: raise RuntimeError('Invalid measured stage')
    if s['gpu_s'] is not None and (not math.isfinite(s['gpu_s']) or s['gpu_s']<0): raise RuntimeError('Invalid measured GPU activity')
